

const lnk = require('lnk');
const path = require('path');
const fs = require('fs');

var arg = process.argv[2]

var isUnlink = false;
if (arg == "false") {
    isUnlink = true
}


var packagesPath = path.resolve('../../', 'Packages')
var srcPath = path.resolve('./', 'src')


function unlink(path) {
    if (fs.existsSync(path)) {
        fs.unlinkSync(path)
    }
}

var files = fs.readdirSync(srcPath);
files.forEach(async file => {
    var filePath = path.resolve(srcPath, file)
    var unlinkPath = path.resolve(packagesPath, file)
    unlink(unlinkPath);
    if (!isUnlink) {
        await lnk(filePath, packagesPath);
    }
});

